import json
import os
import re
import time

from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.logger.custom_logger import log_info_to_console, log_warn_to_console
from taf.rfrl.utilities.transfer_files import upload_files
from taf.rfrl.utilities.wft_api import WftHubApi
from taf.rfrl.bts.devices.asir.asir_antennas_manager.script_files import get_fpga_upgrade_script_files
from taf.rfrl.bts.devices.asir.asir_operations import GnbAsirHubOperations, EnbAsirHubOperations
from taf.rfrl.utilities.settings import SVN_LOGIN, SVN_PASSWORD, CRACOW_PROXY


class AntennasManager:

    def __init__(self, devices, branch="SBTS00", sbts_build=None, bts_type="GNB"):
        self.wft_api = WftHubApi()
        devices = [DeviceFactory.get_device(device) for device in devices] if isinstance(devices[0], str) else devices
        self.devices = [AntennaHubManager(device=device, bts_type=bts_type) for device in devices]
        sbts_build = sbts_build or self.wft_api.get_newest_builds_by_branch_title(branch_title=branch, items_count=1)
        self.sbts_build = sbts_build[0]["version"]

    def download_and_get_upgrade_fpga_script_files(self, login=SVN_LOGIN, password=SVN_PASSWORD, proxy=CRACOW_PROXY):
        """
        Downloads RFSW from sbts build and returns needed files for fpga upgrade script
        """
        script_files = {}
        hub_versions = [device.hub_type for device in self.devices]
        if hub_versions.count(None) > 0:
            self.gather_info_from_all_hubs()
            hub_versions = [device.hub_type for device in self.devices]
        for hub_version in set(hub_versions):
            file_name = "RFSW_{}.txz".format(hub_version)
            self.wft_api.download_rfsw_from_sbts_build_version(self.sbts_build, hub_version,
                                                               new_file_name=file_name, file_path="/tmp/",
                                                               login=login, password=password, proxy=proxy)
            script_files[hub_version] = get_fpga_upgrade_script_files(build_path="/tmp/", file_name=file_name)
        return script_files

    def gather_info_from_all_hubs(self):
        for device in self.devices:
            device.gather_hub_info()

    def check_if_fpga_needs_upgrade(self):
        antennas_to_upgrade = self.get_antennas_per_hub_that_need_upgrade()
        if any(bool(antennas) for antennas in antennas_to_upgrade.values()):
            log_warn_to_console("Antennas that need upgrade: {}".format(
                json.dumps({device.device.name: antennas for device, antennas in antennas_to_upgrade.items()}, indent=2)
            ))
            return True
        log_info_to_console("All antennas are up to date")
        return False

    def get_antennas_per_hub_that_need_upgrade(self):
        """
        returns:
        {
          "device_object": {
            "1": {
              "ant_type": "5G_G3",
              "fpga_version": "0xa5160038",
              "fpga_type": "Factory",
              "dc_status": "DISABLE",
              "ant_image_buf_type": "5G_G3_buf",
              "ant_version": "gen3"
            },
            "9": {
              "ant_type": "5G_G3",
              "fpga_version": "0xa5160038",
              "fpga_type": "Factory",
              "dc_status": "DISABLE",
              "ant_image_buf_type": "5G_G3_buf",
              "ant_version": "gen3"
            }
          }
        }
        """
        newest_fpga_dict = self.wft_api.get_fpga_versions_from_sbts_build_version(self.sbts_build)
        antennas_to_upgrade = {}
        for device in self.devices:
            if device.hub_type is None:
                device.gather_hub_info()
            antennas_to_upgrade[device] = device.get_antennas_that_need_upgrade(newest_fpga_dict[device.hub_type])
        return antennas_to_upgrade

    def factory_all_antennas_that_needed(self, antennas_to_upgrade=None, login=SVN_LOGIN, password=SVN_PASSWORD,
                                         proxy=CRACOW_PROXY):
        """
        Upgrade all antennas on all HUBs that needed
        """
        antennas_to_upgrade = self.get_antennas_per_hub_that_need_upgrade() if antennas_to_upgrade is None \
            else antennas_to_upgrade
        script_files = self.download_and_get_upgrade_fpga_script_files(login=login, password=password, proxy=proxy)
        for device, antennas in antennas_to_upgrade.items():
            if not antennas:
                continue
            log_info_to_console("Copy factory script to hub {}".format(device.device.name))
            device.copy_fpga_image_to_hub(script_files[device.hub_type], antennas)
            log_info_to_console("Factory antennas on hub {}".format(device.device.name))
            device.factory_antennas_fpga(antennas)


class AntennaHubManager:

    def __init__(self, device=None, bts_type="GNB"):
        self.device = device
        self.antennas_info = None
        self.hub_type = None
        self.asir = GnbAsirHubOperations() if bts_type == "GNB" else EnbAsirHubOperations()

    def get_antennas_that_need_upgrade(self, fpga_images_dict):
        antennas_to_upgrade = {}
        for antenna_id, antenna_info in self.antennas_info.items():
            actual_version = antenna_info["fpga_version"]
            newest_version = "".join(fpga_images_dict[antenna_info["ant_version"]].split("_")[:2])
            if int(actual_version, 16) < int(newest_version, 16):
                antennas_to_upgrade[antenna_id] = antenna_info
        return antennas_to_upgrade

    def factory_antennas_fpga(self, antennas_dict):
        self.device.goto_state(state="RU")
        self.device.get_cmd(cmd_name="cd", cmd_params={"path": "/tmp/"})()
        for antenna_id, antenna_info in antennas_dict.items():
            ant_ver = antenna_info["ant_version"]
            if ant_ver is not None:
                script_output = "/tmp/ant_factory_out_{}.txt".format(antenna_id)
                script = "/tmp/{}_prrh_factory_upgrade.sh".format(ant_ver)
                self.device.get_cmd(cmd_name="chmod", cmd_params={"permission": "+x", "filename": script})()
                self.device.get_cmd(cmd_name="run_script",
                                    cmd_params={'script_command': "nohup {} {}  > {} &".format(script, antenna_id,
                                                                                               script_output)})()
                log_info_to_console("Factory script antenna with id {} started".format(antenna_id))
                self.wait_for_factory_fpga_results(antenna_id, antenna_output=script_output)
            else:
                log_warn_to_console("Antenna version not supported")

    def wait_for_factory_fpga_results(self, ant_id, timeout=720, antenna_output="/tmp/ant_factory_out.txt"):
        """
        Parse antenna output file from factory_antennas_fpga and waits for success print
        """
        states = ["is not same as wanted image", "Image is same as ANT", "ANT factory image update failed",
                  "update successful", "need to update again"]
        start_time = time.time()
        while time.time() - start_time < timeout:
            grep_states = " -e ".join(("'" + state + "'" for state in states))
            grep = self.device.get_cmd(cmd_name="grep", cmd_params={"options": "-e " + grep_states + " {}".
                                       format(antenna_output)})()
            for line in grep["LINES"]:
                if "is not same as wanted image" in line:
                    log_info_to_console("Update antenna with id {} started".format(ant_id))
                    del states[0]
                elif "Image is same as ANT's" in line:
                    log_info_to_console("Antenna with id {} not need to update".format(ant_id))
                    return True
                elif "ANT factory image update failed" in line:
                    log_warn_to_console("Antenna with id {} update failed".format(ant_id))
                    return False
                elif "update successful" in line:
                    log_info_to_console("Antenna with id {} update successful".format(ant_id))
                    return True
                elif "need to update again" in line:
                    log_warn_to_console("Antenna with id {} need to update again".format(ant_id))
                    return False
            time.sleep(13)
        else:
            log_warn_to_console("failed to get results from antenna with id {} - there were some problems with"
                                " launching script".format(ant_id))

    @load_moler_configuration_from_tl()
    def gather_hub_info(self):
        self.device.goto_state(state="RU")
        self.antennas_info = self.asir.get_antennas_info(hub_device=self.device)
        for antenna in self.antennas_info.values():
            antenna["ant_version"] = self.get_antenna_version(antenna["fpga_version"])
        prompt = self.device.get_cmd(cmd_name="hostname")()["hostname"]
        if "fzhub20" in prompt:
            self.hub_type = "ASIHUB2.0"
        elif "fzhub" in prompt:
            self.hub_type = "ASIHUB"

    def copy_fpga_image_to_hub(self, script_fpga_images_dict, antennas_dict):
        abs_path = os.path.dirname(os.path.abspath(__file__))
        antennas_version = [antenna["ant_version"] for antenna in antennas_dict.values()]
        for antenna_version in set(antennas_version):
            if antenna_version is not None:
                fpga_image = script_fpga_images_dict[antenna_version]["image"].split("/")
                image_md5 = script_fpga_images_dict[antenna_version]["image_md5"].split("/")
                upload_files(abs_path, "{}_prrh_factory_upgrade.sh".format(antenna_version), self.device.name,
                             "/tmp/", to_state="RU")
                upload_files("/".join(fpga_image[:-1]), fpga_image[-1], self.device.name, "/tmp/", to_state="RU")
                upload_files("/".join(image_md5[:-1]), image_md5[-1], self.device.name, "/tmp/", to_state="RU",
                             new_file_name="image_md5_{}".format(antenna_version))
            else:
                log_warn_to_console("Antenna version not supported")

    @staticmethod
    def get_antenna_version(fpga_version):
        match = re.search(r"0x\w*?(\d{3})", fpga_version)
        if not match:
            return None
        elif match.group(1) == "514":
            return "gen1"
        elif match.group(1) == "515":
            return "gen2"
        elif match.group(1) == "516":
            return "gen3"
